/* Commit 25: Robust Centralized Input Validation & SSRF Prevention */
const items = $input.all();
const results = [];
const DEFAULT_API = 'https://reqres.in/api/users';

for (const item of items) {
  try {
    let rawUrl = null;
    const body = item.json.body || item.json;

    if (typeof body === 'object' && body !== null) {
      rawUrl = body.url;
    } else if (typeof body === 'string') {
      try {
        const parsed = JSON.parse(body);
        rawUrl = parsed.url;
      } catch (e) {
        rawUrl = body;
      }
    }

    if (!rawUrl || typeof rawUrl !== 'string' || rawUrl.trim() === '') {
      rawUrl = DEFAULT_API;
    }

    let targetUrl = rawUrl.replace(/[\x00-\x1F\x7F-\x9F]/g, '').trim().replace(/^['"]|['"]$/g, '');

    if (!targetUrl.startsWith('http://') && !targetUrl.startsWith('https://')) {
      targetUrl = 'https://' + targetUrl;
    }

    let isValid = true;
    let errorType = null;
    let errorMessage = null;

    const urlPattern = /^(https?):\/\/([^/:]+)(?::(\d+))?(.*)$/i;
    const match = targetUrl.match(urlPattern);

    if (!match) {
      isValid = false;
      errorType = 'INVALID_URL';
      errorMessage = 'Malformed URL syntax provided.';
    } else {
      const protocol = match[1].toLowerCase();
      let hostname = match[2].toLowerCase();

      if (hostname.startsWith('[') && hostname.endsWith(']')) {
        hostname = hostname.slice(1, -1);
      }

      if (protocol !== 'http' && protocol !== 'https') {
        isValid = false;
        errorType = 'INVALID_PROTOCOL';
        errorMessage = 'Unsupported protocol. Only HTTP and HTTPS are permitted.';
      } 
      else if (
        hostname === 'localhost' ||
        hostname === '0.0.0.0' ||
        hostname === '::1' ||
        hostname === '0000:0000:0000:0000:0000:0000:0000:0001' ||
        hostname.startsWith('127.') ||
        hostname.startsWith('10.') ||
        hostname.startsWith('192.168.') ||
        /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(hostname) ||
        hostname.startsWith('169.254.') ||
        hostname.endsWith('.internal') ||
        hostname.endsWith('.local') ||
        hostname.endsWith('.lan') ||
        hostname.endsWith('.home') ||
        hostname.endsWith('.corp') ||
        hostname.endsWith('.private')
      ) {
        isValid = false;
        errorType = 'SSRF_RESTRICTED_TARGET';
        errorMessage = 'Target points to a restricted internal, loopback, or metadata address.';
      }
    }

    if (!isValid) {
      results.push({
        json: {
          status: 'error',
          error_code: errorType,
          url: targetUrl,
          message: errorMessage,
          start_time: Date.now(),
          timestamp: new Date().toISOString()
        }
      });
    } else {
      results.push({
        json: {
          status: 'ready_for_scan',
          error_code: null,
          url: targetUrl,
          message: null,
          start_time: Date.now(),
          timestamp: new Date().toISOString()
        }
      });
    }
  } catch (err) {
    results.push({
      json: {
        status: 'error',
        error_code: 'VALIDATION_EXCEPTION',
        url: 'unknown',
        message: 'An unexpected exception occurred during input validation.',
        start_time: Date.now(),
        timestamp: new Date().toISOString()
      }
    });
  }
}

return results;

/* Commit 25: Robust Response Normalization, Bounded Body Inspection & Size Limits */
const items = $input.all();
const results = [];
const MAX_BODY_BYTES = 500 * 1024;

for (const item of items) {
  try {
    const res = item.json;
    const validateData = $('Validate Input').item?.json || {};
    const targetUrl = validateData.url || 'unknown';
    const startTime = validateData.start_time || Date.now();
    const endTime = Date.now();
    const responseTimeMs = Math.max(0, endTime - startTime);

    if (res.error || (res.statusCode >= 500 && !res.body)) {
      let errCode = 'NETWORK_ERROR';
      let msg = res.error?.message || res.message || 'Failed to reach target endpoint.';

      if (msg.includes('ENOTFOUND') || msg.includes('getaddrinfo')) {
        errCode = 'DNS_LOOKUP_FAILED';
        msg = 'Domain resolution failed (host not found).';
      } else if (msg.includes('ETIMEDOUT') || msg.includes('timeout') || msg.includes('ESOCKETTIMEDOUT')) {
        errCode = 'CONNECTION_TIMEOUT';
        msg = 'Target server timed out after configured threshold.';
      } else if (msg.includes('ECONNREFUSED')) {
        errCode = 'CONNECTION_REFUSED';
        msg = 'Connection refused by target host.';
      }

      results.push({
        json: {
          status: 'error',
          error_code: errCode,
          url: targetUrl,
          message: msg,
          start_time: startTime,
          timestamp: new Date().toISOString()
        }
      });
      continue;
    }

    const statusCode = res.statusCode || 200;
    const rawHeaders = res.headers || {};
    const normalizedHeaders = {};

    for (const [key, val] of Object.entries(rawHeaders)) {
      const lowerKey = key.toLowerCase();
      if (['authorization', 'cookie', 'set-cookie', 'x-api-key', 'token', 'bearer', 'sec-websocket-key'].includes(lowerKey)) {
        normalizedHeaders[lowerKey] = '[REDACTED]';
      } else {
        normalizedHeaders[lowerKey] = val;
      }
    }

    const contentTypeHeader = normalizedHeaders['content-type'] || '';
    const isJson = contentTypeHeader.includes('application/json');
    const isXml = contentTypeHeader.includes('application/xml') || contentTypeHeader.includes('text/xml');
    const isHtml = contentTypeHeader.includes('text/html');

    let bodySizeBytes = 0;
    const rawBody = res.body;
    let bodyString = '';

    if (rawBody) {
      if (typeof rawBody === 'string') {
        bodyString = rawBody;
      } else if (typeof rawBody === 'object') {
        try {
          bodyString = JSON.stringify(rawBody);
        } catch (e) {
          bodyString = '[UNSERIALIZABLE_BODY]';
        }
      }
      bodySizeBytes = Buffer.byteLength(bodyString, 'utf8');
    } else if (normalizedHeaders['content-length']) {
      bodySizeBytes = parseInt(normalizedHeaders['content-length'], 10) || 0;
    }

    if (bodySizeBytes > MAX_BODY_BYTES) {
      results.push({
        json: {
          status: 'error',
          error_code: 'RESPONSE_SIZE_EXCEEDED',
          url: targetUrl,
          message: `Response size (${bodySizeBytes} bytes) exceeds safety maximum.`,
          start_time: startTime,
          timestamp: new Date().toISOString()
        }
      });
      continue;
    }

    const sanitizedBodySnippet = bodyString.length > 50000 ? bodyString.substring(0, 50000) + '...[TRUNCATED]' : bodyString;

    const normalizedScan = {
      status: statusCode >= 400 ? 'http_error' : 'scan_completed',
      target: {
        url: targetUrl,
        status_code: statusCode,
        response_time_ms: responseTimeMs
      },
      metadata: {
        content_type: contentTypeHeader || 'unknown',
        content_length_bytes: bodySizeBytes,
        is_json: isJson,
        is_xml: isXml,
        is_html: isHtml
      },
      headers: normalizedHeaders,
      _internal_body_snippet: sanitizedBodySnippet,
      start_time: startTime,
      timestamp: new Date().toISOString()
    };

    results.push({
      json: normalizedScan
    });
  } catch (normErr) {
    results.push({
      json: {
        status: 'error',
        error_code: 'MALFORMED_RESPONSE',
        url: 'unknown',
        message: 'Failed to normalize target response.',
        start_time: Date.now(),
        timestamp: new Date().toISOString()
      }
    });
  }
}

return results;

/* Commit 25: Analyze HTTP Metadata with Fault Protection */
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  if (data.status === 'error') {
    results.push({ json: data });
    continue;
  }

  const statusCode = data.target?.status_code || 0;
  const contentType = data.metadata?.content_type || '';
  const isHtml = data.metadata?.is_html || false;

  let statusCategory = 'unknown';
  if (statusCode >= 100 && statusCode < 200) statusCategory = 'informational';
  else if (statusCode >= 200 && statusCode < 300) statusCategory = 'success';
  else if (statusCode >= 300 && statusCode < 400) statusCategory = 'redirection';
  else if (statusCode >= 400 && statusCode < 500) statusCategory = 'client_error';
  else if (statusCode >= 500 && statusCode < 600) statusCategory = 'server_error';

  const findings = [];

  if (statusCategory === 'server_error') {
    findings.push({
      code: 'SERVER_ERROR_RESPONSE',
      type: 'operational_risk',
      severity: 'medium',
      message: `Target returned HTTP status ${statusCode} (Internal Server Error).`
    });
  }

  if (!contentType || contentType === 'unknown') {
    findings.push({
      code: 'MISSING_CONTENT_TYPE',
      type: 'security_header',
      severity: 'low',
      message: 'Response is missing a Content-Type header.'
    });
  }

  if (isHtml) {
    findings.push({
      code: 'HTML_RESPONSE_ON_API',
      type: 'content_anomaly',
      severity: 'low',
      message: 'Target returned an HTML body instead of structured API data.'
    });
  }

  results.push({
    json: {
      ...data,
      http_analysis: {
        status_category: statusCategory,
        is_success: statusCategory === 'success',
        metadata_findings: findings,
        findings_count: findings.length
      }
    }
  });
}

return results;

/* Commit 25: Analyze HTTPS & Transport */
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  if (data.status === 'error') {
    results.push({ json: data });
    continue;
  }

  const urlStr = data.target?.url || '';
  const isHttps = urlStr.toLowerCase().startsWith('https://');
  const headers = data.headers || {};
  const hstsHeader = headers['strict-transport-security'] || null;

  const findings = [];
  let hstsDetails = { present: false, max_age_seconds: null, include_subdomains: false, preload: false };

  if (!isHttps) {
    findings.push({
      code: 'UNENCRYPTED_TRANSPORT_HTTP',
      type: 'transport_security',
      severity: 'high',
      message: 'Target uses cleartext HTTP.'
    });
  } else if (!hstsHeader) {
    findings.push({
      code: 'MISSING_HSTS_HEADER',
      type: 'transport_security',
      severity: 'low',
      message: 'Strict-Transport-Security header is missing.'
    });
  } else {
    hstsDetails.present = true;
  }

  results.push({
    json: {
      ...data,
      https_analysis: {
        is_https: isHttps,
        scheme: isHttps ? 'https' : 'http',
        hsts: hstsDetails,
        transport_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Analyze Security Headers */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }
  const headers = data.headers || {};
  const findings = [];

  const xcto = headers['x-content-type-options'];
  if (!xcto || !xcto.toLowerCase().includes('nosniff')) {
    findings.push({ code: 'MISSING_X_CONTENT_TYPE_OPTIONS', type: 'security_header', severity: 'medium', message: 'X-Content-Type-Options header is missing or not set to nosniff.' });
  }

  const xfo = headers['x-frame-options'];
  if (!xfo) {
    findings.push({ code: 'MISSING_X_FRAME_OPTIONS', type: 'security_header', severity: 'low', message: 'X-Frame-Options header is missing.' });
  }

  const csp = headers['content-security-policy'];
  if (!csp) {
    findings.push({ code: 'MISSING_CONTENT_SECURITY_POLICY', type: 'security_header', severity: 'low', message: 'Content-Security-Policy header is missing.' });
  }

  results.push({
    json: {
      ...data,
      security_headers_analysis: {
        headers_evaluated: {
          x_content_type_options: xcto || null,
          x_frame_options: xfo || null,
          content_security_policy: csp ? 'present' : null
        },
        header_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Analyze CORS Configuration */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }
  const headers = data.headers || {};
  const findings = [];
  const allowOrigin = headers['access-control-allow-origin'] || null;
  if (allowOrigin === '*') {
    findings.push({ code: 'WILDCARD_CORS_ORIGIN', type: 'cors_configuration', severity: 'low', message: 'Access-Control-Allow-Origin is set to wildcard (*).' });
  }
  results.push({
    json: {
      ...data,
      cors_analysis: {
        cors_evaluated: { allow_origin: allowOrigin },
        cors_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Analyze Information Disclosure */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }
  const headers = data.headers || {};
  const findings = [];
  const server = headers['server'];
  const poweredBy = headers['x-powered-by'];

  if (server) {
    findings.push({ code: 'SERVER_HEADER_EXPOSED', type: 'info_disclosure', severity: 'low', message: `Server header exposed: ${server}` });
  }
  if (poweredBy) {
    findings.push({ code: 'X_POWERED_BY_EXPOSED', type: 'info_disclosure', severity: 'low', message: `X-Powered-By header exposed: ${poweredBy}` });
  }

  const techDetected = [];
  if (server) techDetected.push(server);
  if (poweredBy) techDetected.push(poweredBy);

  results.push({
    json: {
      ...data,
      info_disclosure_analysis: {
        technologies_detected: techDetected,
        disclosure_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Analyze Error Exposure */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }

  const findings = [];
  const bodySnippet = data._internal_body_snippet || '';

  if (/stack\s*trace|exception|traceback|syntaxerror|fatal\s*error/i.test(bodySnippet)) {
    findings.push({
      code: 'VERBOSE_ERROR_TRACE_EXPOSED',
      type: 'error_exposure',
      severity: 'medium',
      message: 'Response body contains verbose exception or stack trace details.'
    });
  }

  const cleanData = { ...data };
  delete cleanData._internal_body_snippet;

  results.push({
    json: {
      ...cleanData,
      error_exposure_analysis: {
        error_exposure_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Analyze Rate Limits */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }

  const headers = data.headers || {};
  const hasRateLimitHeaders = Object.keys(headers).some(h => 
    h.includes('ratelimit') || h.includes('retry-after')
  );

  const findings = [];
  if (!hasRateLimitHeaders) {
    findings.push({
      code: 'MISSING_RATE_LIMIT_HEADERS',
      type: 'rate_limiting',
      severity: 'low',
      message: 'No rate-limiting headers detected in HTTP response.'
    });
  }

  results.push({
    json: {
      ...data,
      rate_limit_analysis: {
        has_rate_limit_headers: hasRateLimitHeaders,
        rate_limit_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Analyze JSON Quality */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }

  const isJson = data.metadata?.is_json || false;
  const findings = [];

  if (!isJson) {
    findings.push({
      code: 'NON_JSON_RESPONSE_FORMAT',
      type: 'json_quality',
      severity: 'low',
      message: 'Target response content-type is not JSON.'
    });
  }

  results.push({
    json: {
      ...data,
      json_quality_analysis: {
        summary: { is_valid_json: isJson },
        quality_findings: findings,
        findings_count: findings.length
      }
    }
  });
}
return results;

/* Commit 25: Unified Findings Engine */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }

  const rawFindings = [
    ...(data.http_analysis?.metadata_findings || []),
    ...(data.https_analysis?.transport_findings || []),
    ...(data.security_headers_analysis?.header_findings || []),
    ...(data.cors_analysis?.cors_findings || []),
    ...(data.info_disclosure_analysis?.disclosure_findings || []),
    ...(data.error_exposure_analysis?.error_exposure_findings || []),
    ...(data.rate_limit_analysis?.rate_limit_findings || []),
    ...(data.json_quality_analysis?.quality_findings || [])
  ];

  const unifiedFindings = rawFindings.map((f, idx) => ({
    id: f.code?.toLowerCase() || `finding_${idx+1}`,
    category: f.type || 'security',
    severity: f.severity || 'low',
    title: f.code?.replace(/_/g, ' ') || 'Finding',
    description: f.message || '',
    source: 'deterministic'
  }));

  results.push({
    json: {
      ...data,
      unified_findings: {
        total_findings: unifiedFindings.length,
        findings: unifiedFindings
      }
    }
  });
}
return results;

/* Commit 25: Risk Scoring Engine */
const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  if (data.status === 'error') { results.push({ json: data }); continue; }

  const findings = data.unified_findings?.findings || [];
  let penalty = findings.reduce((acc, f) => acc + (f.severity === 'high' ? 15 : f.severity === 'medium' ? 8 : 3), 0);
  const score = Math.max(0, 100 - penalty);
  let rating = score >= 90 ? 'Excellent' : score >= 75 ? 'Good' : score >= 60 ? 'Needs Improvement' : 'Critical';

  results.push({
    json: {
      ...data,
      risk_scoring: { score, rating, total_penalty_points: penalty }
    }
  });
}
return results;

/* Commit 25: Centralized AI Fallback & Failure Formatter */
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  if (data.status === 'error') {
    results.push({ json: data });
    continue;
  }

  const isAiError = data.error || !data.output;
  let aiSummary = isAiError 
    ? 'AI analysis unavailable or unconfigured. Audit conclusions rely strictly on deterministic static analysis rules.' 
    : data.output;

  const finalPayload = {
    ...data,
    ai_analysis: {
      status: isAiError ? 'unavailable' : 'completed',
      summary: aiSummary
    }
  };

  delete finalPayload.output;
  delete finalPayload.error;

  results.push({ json: finalPayload });
}

return results;

